src='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    markers = {value for row in grid for value in row if value != background}
    marker = next(iter(markers))
    out = [row[:] for row in grid]
    for r in range(h):
        hits = [c for c in range(w) if grid[r][c] == marker]
        if hits:
            for c in range(hits[0], hits[-1] + 1):
                if grid[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        hits = [r for r in range(h) if grid[r][c] == marker]
        if hits:
            for r in range(hits[0], hits[-1] + 1):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
